import{z as l,x as o,o as e,c as d,q as n,j as r,D as E,d as A,s as i,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"日内季节性的稳定形态","description":"","frontmatter":{"title":"日内季节性的稳定形态","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/obd-intraday-seasonality.md","filePath":"quant/obd-intraday-seasonality.md","lastUpdated":1791063341000}'),p={name:"quant/obd-intraday-seasonality.md"};function D(m,a,u,h,c,C){const t=o("Mermaid");return e(),d("div",null,[a[2]||(a[2]=n('<h1 id="日内季节性的稳定形态" tabindex="-1">日内季节性的稳定形态 <a class="header-anchor" href="#日内季节性的稳定形态" aria-label="Permalink to &quot;日内季节性的稳定形态&quot;">​</a></h1><div class="epigraph"><p>日内形状比它的幅度可靠得多：峰谷的幅度随体制伸缩，相位却极少搬家——形状整体搬家那天，多半是规则改了。</p><footer>—— 据 Andersen and Bollerslev, Journal of Empirical Finance, 1997；Harris, Trading and Exchanges, 2003；Bouchaud 等, Trades, Quotes and Prices, 2018 整理</footer></div><p><a href="/quant/obd-adverse-dynamic">上一课</a>把价差写成状态函数之后，一个被低估的状态变量浮出水面：现在是交易日的几点。波动的日内周期主干在<a href="/quant/intraday-seasonality">日内季节性</a>讲过：怎么估 \\(s_i\\)、怎么去季节。本课进入「截面与时间」单元，把对象换成形状本身——成交、点差、深度、毒性各自的日内形状有多稳定，什么时候整体搬家。分工是：主干课管估计，本课管稳定性。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>去季节这个动作默认了形状可估且稳。但形状跨日、跨票、跨体制会变：危机年的开盘峰比平常高出一截，被动化改变收盘的堆积，拍卖规则一改，两端形状整体搬家。用不稳的形状去季节，体制变化就埋进残差，下游的 GARCH、跳跃检验、毒性回归全部承接伪持续。缺口不是再估一次 \\(s_i\\)，而是回答：形状的哪些性质值得当常数用，哪些必须跟着体制走。</p><p><span class="marginnote">术语翻译：去季节就是把原始读数除以「同时刻的历史平均形状」，得到相对正常水平的残差。若形状本身估歪了，残差里会留下每天准时报到的假信号——下游模型会把它当新发现，其实是日历在冒充信息。</span></p><h3 id="稳定什么-不稳定什么" tabindex="-1">稳定什么，不稳定什么 <a class="header-anchor" href="#稳定什么-不稳定什么" aria-label="Permalink to &quot;稳定什么，不稳定什么&quot;">​</a></h3><p>经验上稳定的是相位：成交、点差、深度的峰谷位置——开盘与收盘堆积、会话中段凹陷——由交易时间表与机构流程决定，流程不变则相位不动。不稳定的是幅度：同一只票不同年份的峰高可以差数倍。这条不对称给出使用规则：相位可以当结构写进模型（第一课按会话分段的速率族就是用法），幅度必须滚动估计。形状整体搬家几乎总有制度原因：会话结构调整、tick 与费率改革、拍卖规则修改、参与者结构迁移。</p><p><span class="marginnote">三个形状互检是便宜的诊断：成交量、点差、深度的日内形状应大致同相位。若点差峰与成交峰错开几个格子，多半不是市场现象而是数据问题——竞价成交被并进连续时段，或会话边界切错。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先对齐再谈稳定：交易时钟而非墙钟、午休切分、提前收盘日单独处理——口径主干课已立好，本课在其上做三层检验。其一，跨日稳定性：滚动窗内逐日形状对基准的距离分布，秩相关比均方距离更能抵抗幅度漂移。其二，跨票稳定性：个股形状与市场聚合形状对齐比较，大盘与指数的形状通常比小票稳。其三，崩坏检测：规则改动日前后做形状对照，把「形状搬家日」登记成制度事件清单，供下一课与事件研究课使用。</p><p>稳定形状是速率方程的基线：第一课的分段强度、第四课毒性的日内先验、后面噪声与事件研究的时间控制，都吃这份形状。崩坏日不进基线：剔除或单独成段，否则形状被极端体制绑死。</p>',12)),(e(),r(s,null,{default:E(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20AL%5B%22%E4%BA%A4%E6%98%93%E6%97%B6%E9%92%9F%E5%AF%B9%E9%BD%90%20%2B%20%E4%BC%9A%E8%AF%9D%E5%88%87%E5%88%86%22%5D%20--%3E%20EST%5B%22%E9%80%90%E6%97%A5%E5%BD%A2%E7%8A%B6%E4%BC%B0%E8%AE%A1%22%5D%0A%20%20EST%20--%3E%20CH%5B%22%E8%B7%A8%E6%97%A5%E8%B7%9D%E7%A6%BB%E4%B8%8E%E7%A7%A9%E7%9B%B8%E5%85%B3%22%5D%0A%20%20EST%20--%3E%20XS%5B%22%E8%B7%A8%E7%A5%A8%E5%AF%B9%E9%BD%90%E6%AF%94%E8%BE%83%22%5D%0A%20%20CH%20--%3E%20ST%7B%22%E7%9B%B8%E4%BD%8D%E7%A8%B3%E5%AE%9A%EF%BC%9F%22%7D%0A%20%20XS%20--%3E%20ST%0A%20%20ST%20--%3E%7C%E6%98%AF%7C%20BASE%5B%22%E6%BB%9A%E5%8A%A8%E5%B9%85%E5%BA%A6%E5%9F%BA%E7%BA%BF%22%5D%0A%20%20ST%20--%3E%7C%E5%90%A6%7C%20BRK%5B%22%E7%99%BB%E8%AE%B0%E4%B8%BA%E5%88%B6%E5%BA%A6%E4%BA%8B%E4%BB%B6%EF%BC%8C%E5%89%94%E9%99%A4%E6%88%96%E5%8D%95%E7%8B%AC%E6%AE%B5%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[A("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"形状来自日历与流程：开盘承接隔夜信息、做市商重建报价，收盘服务指数与拍卖需求，午间参与率塌陷。稳定性是机构流程惯性的度量——流程不变，相位不变。幅度不稳定的机制是体制：波动、参与率、被动资金占比都乘在形状上，\\(\\sigma_{t,i}\\approx s_i\\tilde\\sigma_{t,i}\\) 的相对轮廓稳、绝对水平随体制缩放。读反了会错在哪：把幅度当结构，模型每年重估「结构性」参数；把相位当体制，规则改动后拿旧相位硬套，开盘段全部错位。",-1)),a[5]||(a[5]=B("p",null,"相位与幅度各自由谁决定，决定了它们该不该当常数用：",-1)),(e(),r(s,null,{default:E(()=>[i(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCH%5B%22%E4%BA%A4%E6%98%93%E6%97%B6%E9%97%B4%E8%A1%A8%E4%B8%8E%E6%9C%BA%E6%9E%84%E6%B5%81%E7%A8%8B%22%5D%20--%3E%20OP%5B%22%E5%BC%80%E7%9B%98%3A%E6%89%BF%E6%8E%A5%E9%9A%94%E5%A4%9C%E4%BF%A1%E6%81%AF%2B%E9%87%8D%E5%BB%BA%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20SCH%20--%3E%20MID%5B%22%E5%8D%88%E9%97%B4%3A%E5%8F%82%E4%B8%8E%E7%8E%87%E5%A1%8C%E9%99%B7%22%5D%0A%20%20SCH%20--%3E%20CL%5B%22%E6%94%B6%E7%9B%98%3A%E6%8C%87%E6%95%B0%E4%B8%8E%E6%8B%8D%E5%8D%96%E9%9C%80%E6%B1%82%E5%A0%86%E7%A7%AF%22%5D%0A%20%20OP%20--%3E%20PH%5B%22%E5%B3%B0%E8%B0%B7%E4%BD%8D%E7%BD%AE%3D%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20MID%20--%3E%20PH%0A%20%20CL%20--%3E%20PH%0A%20%20REG%5B%22%E5%BD%93%E6%97%A5%E4%BD%93%E5%88%B6%3A%E6%B3%A2%E5%8A%A8%2F%E5%8F%82%E4%B8%8E%E7%8E%87%2F%E8%A2%AB%E5%8A%A8%E5%8D%A0%E6%AF%94%22%5D%20--%3E%20AMP%5B%22%E5%B3%B0%E8%B0%B7%E9%AB%98%E4%BD%8E%3D%E5%B9%85%E5%BA%A6%22%5D%0A%20%20PH%20--%3E%20USE%5B%22%E7%9B%B8%E4%BD%8D%E5%BD%93%E7%BB%93%E6%9E%84%E5%86%99%E8%BF%9B%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20AMP%20--%3E%20USE2%5B%22%E5%B9%85%E5%BA%A6%E6%BB%9A%E5%8A%A8%E4%BC%B0%E8%AE%A1%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">数字实例：某票开盘峰是日均成交的 3 倍、午间谷是 0.4 倍；活跃年份整体翻倍后峰变 6 倍、谷 0.8 倍——峰谷位置没动（相位稳），高低差了一倍（幅度漂）。秩相关接近 1 而方差比远大于 1，正是两种稳定性的量化分野。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>短样本撑不起稳定性检验：新上市与近年改过规则的品种只能借同市场聚合形状，并声明风险。跨市场不可混估：有午休、竞价制度不同的市场，形状不能平均。公告日是形状内的例外而非新形状：瞬时抬高单列为公告效应，写进 \\(s_i\\) 会污染普通日。形状稳定性是假设而非定理：检验给出「何时可当常数」的判据，给出不了永远。</p><p><span class="marginnote">这一步如果做错了，后面全错：形状基线歪一天，毒性回归就多出一个「每天下午准时变毒」的假体制，事件研究把公告效应误记进普通日形状。所有「日内模式」结论，先要过形状这一关。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课对象是日内形状的稳定性：相位稳、幅度随体制伸缩，这是使用规则的全部依据。</li><li>检验三层：跨日距离与秩相关、跨票对齐、规则改动日的崩坏登记。</li><li>稳定形状的用途：速率基线、毒性先验、事件研究的时间控制；崩坏日剔除。</li><li>形状整体搬家几乎总是制度事件，应登记成清单供后续课使用。</li><li>出处：Andersen and Bollerslev, <em>Journal of Empirical Finance</em>, 1997；日内剖面见 Bouchaud 等, <em>Trades, Quotes and Prices</em>, 2018；估计方法见<a href="/quant/intraday-seasonality">日内季节性</a>。</li></ul>',6))])}const S=l(p,[["render",D]]);export{f as __pageData,S as default};
